from ortools.linear_solver import pywraplp
import math
import json

def main():
    neighborhoods = ['Alpha', 'Beta', 'Gamma', 'Delta', 'Epsilon', 'Zeta', 'Eta', 'Theta', 'Iota', 'Kappa']

    east = {
        'Alpha': 5, 'Beta': 25, 'Gamma': 10, 'Delta': 40, 'Epsilon': 55,
        'Zeta': 35, 'Eta': 70, 'Theta': 85, 'Iota': 60, 'Kappa': 95
    }

    north = {
        'Alpha': 15, 'Beta': 5, 'Gamma': 30, 'Delta': 20, 'Epsilon': 50,
        'Zeta': 65, 'Eta': 45, 'Theta': 80, 'Iota': 90, 'Kappa': 10
    }

    demand = {
        'Alpha': 4, 'Beta': 6, 'Gamma': 7, 'Delta': 5, 'Epsilon': 8,
        'Zeta': 3, 'Eta': 9, 'Theta': 2, 'Iota': 6, 'Kappa': 4
    }

    capacity = 25
    num_depots = 3
    N = neighborhoods

    distance = {}
    for i in N:
        for j in N:
            dx = east[i] - east[j]
            dy = north[i] - north[j]
            distance[(i, j)] = math.sqrt(dx*dx + dy*dy)

    solver = pywraplp.Solver.CreateSolver('SCIP')
    if not solver:
        print('Could not create solver')
        return

    assign = {}
    for i in N:
        for j in N:
            assign[(i, j)] = solver.BoolVar(f'assign_{i}_{j}')

    is_depot = {}
    for j in N:
        is_depot[j] = solver.BoolVar(f'is_depot_{j}')

    for i in N:
        solver.Add(sum(assign[(i, j)] for j in N) == 1)

    for i in N:
        for j in N:
            solver.Add(assign[(i, j)] <= is_depot[j])

    solver.Add(sum(is_depot[j] for j in N) == num_depots)

    for j in N:
        solver.Add(sum(demand[i] * assign[(i, j)] for i in N) <= capacity)

    objective = solver.Sum(distance[(i, j)] * assign[(i, j)] for i in N for j in N)
    solver.Minimize(objective)

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL:
        total_cost = solver.Objective().Value()

        depot_locations = [j for j in N if is_depot[j].solution_value() > 0.5]

        service_allocations = {}
        for i in N:
            for j in N:
                if assign[(i, j)].solution_value() > 0.5:
                    service_allocations[i] = j
                    break

        name_to_index = {name: idx + 1 for idx, name in enumerate(neighborhoods)}
        depot_indices = [name_to_index[depot] for depot in depot_locations]
        allocation_indices = [name_to_index[service_allocations[neighborhood]] for neighborhood in neighborhoods]

        print(json.dumps({
            "total_cost": total_cost,
            "depot_locations": depot_indices,
            "service_allocations": allocation_indices
        }))
    else:
        print(json.dumps({
            "total_cost": None,
            "depot_locations": [],
            "service_allocations": []
        }))

if __name__ == '__main__':
    main()
